);
final stopwatch = Stopwatch()..start();
// Issue #332: a resume runs inline (no TaskJob), so it gets a cancel
// source like a blocking spawn — `task_cancel` / `/tasks cancel` abort
// the live resume instead of tombstoning the row over it. Registered
// BEFORE the warm-wake window: from here on the row reads running, so
// concurrent task_send routes through the inbox instead of racing the
// boot.
final resumeCancel = CancelTokenSource();
_resumesInFlight.add(id);
_currentSubagentIds.add(id);
_inFlightCancels[id] = resumeCancel;
Agent? child;
void Function()? untrackUsage;
StreamSubscription<void>? inboxWakeSub;
var semaphoreAcquired = false;
List<SubagentMessage> mail = const [];
// gh-1951 AC6: a reply acked in a PREVIOUS life whose completion never
// surfaced it (kill mid-run) is carried onto this resume — persisted
// as a complete artifact so the completion surfaces it out of band
// (I4), and snapshotted as the result's reply when this run records
// none of its own. Inside the try: a persist failure fails the resume
// with a NAMED error — never a silent loss.
String? pendingReply;
try {
  pendingReply = manager.carryPendingReply(id);
  if (pendingReply != null) {
    _capture?.persistCarriedReply(id, pendingReply);
  }
  await manager.update(
    id,
    status: SubagentStatus.running,
    clearError: true,
  );
  await manager.update(
    id,
    status: SubagentStatus.running,
    clearError: true,
  );

  // Warm wake (issue #647): the message lands in the child's inbox
  // FIRST (durable, instant), then the resume run's first action drains
  // the inbox — consumption never waits out the session boot. The
  // drained mail becomes the prompt with its sender attributed; if the
  // resume fails the mail goes back to the inbox (at-least-once).
  await manager.enqueueMessage(
    id,
    SubagentMessage(
      fromId: manager.selfId,
      text: message,
      sentAt: DateTime.now().toUtc().toIso8601String(),
    ),
    // The parent's steering IS the child's next prompt: verbatim, so
    // the over-window guard still sees its true size (an 8000-char
    // mailbox cap would silently truncate it and slip an oversized
    // request past the guard).
    capText: false,
  );
  mail = await manager.drainMessages(id);
  final since = mail.isEmpty ? null : DateTime.tryParse(mail.first.sentAt);
  deliveryStage(id, 'consumed', since: since);
  final promptText = mail.isEmpty
      ? message
      : mail.map((m) => 'from ${m.fromId}: ${m.text}').join('\n');
  final session = await _resumeSession(id, handle);
  final prior = await session.buildContextMessages();
  _childSessions[id] = session;
  _childSessionWrites[id] = await _appendedMessageCount(session);
  deliveryStage(id, 'wake', since: since);
  await semaphore.acquire();
  semaphoreAcquired = true;
  final resumeRegistry = _childToolRegistry(
    _resolveDefinition(handle.agentType),
  );
  final (built, wakeSub, wiring) = _buildResumeChild(
    id: id,
    handle: handle,
    manager: manager,
    toolRegistry: resumeRegistry,
  );
  child = built;

/// Records the child's explicit `reply` (Phase 3b) on its handle.
///
/// gh-1951: the outcome is explicit because the ack must be truthful —
/// [ReplyRecordOutcome.noHandle] means NOTHING was recorded and the
/// caller (the `reply` tool) must return an error, never a false
/// "delivered". A double reply is idempotent (edge case): the FIRST
/// reply stays the deliverable; later calls are counted as
/// [SubagentHandle.duplicateReplies] and never overwrite it.
Future<ReplyRecordOutcome> recordReply(String id, String text) async {
  final handle = _handles[id];
  if (handle == null) return ReplyRecordOutcome.noHandle;
  if (handle.lastReply != null) {
    handle.duplicateReplies++;
    handle.lastActivity = clock().toIso8601String();
    _events.add(SubagentEvent(handle: handle));
    _persist();
    return ReplyRecordOutcome.duplicateNoted;
  }
  handle.lastReply = text.length > maxReplyChars
      ? '${text.substring(0, maxReplyChars)}…[truncated]'
      : text;
  handle.lastActivity = clock().toIso8601String();
  _events.add(SubagentEvent(handle: handle));
  // gh-1590: coalesced — the parent-visible record lives on the handle
  // (read by every result build); the registry row carries the preview.
  _persist();
  return ReplyRecordOutcome.recorded;
}

/// Awaits the serialized durable registry snapshot (gh-1951 AC2
/// ordering): the `reply` tool acks only after the parent-visible
/// record is durable. Unlike [flushPersist] this never disposes the
/// persist throttle — teardown keeps using it.
Future<void> persistNow() {
  _persist(force: true);
  return _persistChain;
}

/// gh-1951 AC6, called at RESUME start: snapshots and clears any
/// undelivered reply left by a previous child life. The executor
/// persists the snapshot as a carried artifact (so the resume completion
/// surfaces the pointer) and falls back to it when the resumed run
/// records no reply of its own. Returns the carried reply, or null.
String? carryPendingReply(String id) {
  final handle = _handles[id];
  if (handle == null) return null;
  final pending = handle.lastReply;
  if (pending == null && handle.duplicateReplies == 0) return null;
  handle.lastReply = null;
  handle.duplicateReplies = 0;
  _events.add(SubagentEvent(handle: handle));
  _persist();
  return pending;
}

/// Attaches the child's real session file to its handle (called by the
/// executor at child completion when a session factory is wired). The
/// handle's placeholder id becomes the real JSONL path used by
/// `/agents open <id>` and `task_observe`.
Future<void> attachSession(String id, String sessionPath) async {
  final handle = _handles[id];
  if (handle == null) return;
  handle.sessionId = sessionPath;
  handle.lastActivity = clock().toIso8601String();
  _events.add(SubagentEvent(handle: handle));
  // Durability-critical: the real session path must survive a process
  // death (`/agents open <id>` reads it from the registry).
  _persist(force: true);
}

/// Closes the event stream, flushing a coalesced registry snapshot
/// first (gh-1590): a host tearing the manager down must not lose the
/// conversational mutations that coalesced inside the persist window.
Future<void> close() async {
  await flushPersist();
  await _events.close();
}

/// gh-1590: the shutdown flush — a coalesced snapshot lands NOW (the
/// deduper suppresses a no-op) and the throttle's trailing Timer leg
/// disarms: a pending Timer must never hold the isolate at process
/// exit, and a reply/message that settled inside the persist window
/// must still reach the file. Drains the persist chain before
/// returning.
Future<void> flushPersist() {
  _persistThrottle.dispose();
  _persist(force: true);
