```dart
/// Line-leading envelope markers (review thread 4): the reply body is
/// untrusted child text — a line-leading structural marker inside the
/// body could close the block early or forge deliverable verdict lines
/// (the same synthetic-line class `_cleanReportId` defuses for ids).
final RegExp _envelopeMarkerLine = RegExp(
 r'^\s*\[(?:explicit reply(?: end)?|deliverable[ :]|completed_without_reply|'
 r'Full output:|Truncated output:)',
);

/// Defuses line-leading envelope markers in untrusted child text: the
/// brackets of a marker-shaped line are stripped (same structural-char
/// strip `_cleanReportId` applies to ids) so the rendered envelope cannot
/// be closed early or acquire forged verdict/pointer lines. Best-effort:
/// the body remains model-facing raw text.
String _defuseEnvelopeMarkers(String body) {
 return body.split('\n').map((line) {
   if (!_envelopeMarkerLine.hasMatch(line)) return line;
   return line.replaceAll('[', '').replaceAll(']', '');
 }).join('\n');
}
``

