          fromId: m.fromId,
          text: m.text,
          sentAt: m.sentAt,
          hops: m.hops,
          isUserInput: m.kind == AgentMessageKind.user,
          toId: m.toId,
        ),
    ];
  }
  final handle = _handles[id];
  if (handle == null) return const [];
  final drained = List<SubagentMessage>.of(handle.pendingMessages);
  handle.pendingMessages.clear();
  return drained;
}

